1766	            posix.F.SETFL,
1767	            flags | @as(u32, @bitCast(posix.O{ .NONBLOCK = true })),
1768	        ))) {
1769	            .SUCCESS => {},
1770	            else => |e| {
1771	                log.warn("read thread failed to set flags err=E{s}", .{@tagName(e)});
1772	                return false;
1773	            },
1774	        }
1775	        return true;
1776	    }
